response:
{
  "id": "supply-demand-equilibrium",
  "title": "供需曲线与市场均衡",
  "subtitle": "从直觉到模型，看懂价格如何被决定",
  "language": "zh-CN",
  "audience": "经济学初学者/本科低年级",
  "theme": "cobalt-grid",
  "tutor": {
    "suggestions": [
      "水对生存必不可少却便宜，钻石没用却很贵，这违背需求定律吗？",
      "政府规定最高房租，为什么反而让穷人更难租到房？",
      "税收是向商家征收的，为什么说消费者也承担了税负？",
      "股票市场追涨杀跌，说明需求曲线可以向上倾斜吗？"
    ],
    "kb": [
      {
        "pattern": "需求定律|需求法则",
        "answer": "在其他条件不变时，商品的需求量与价格呈反方向变动：价涨量跌，价跌量涨。"
      },
      {
        "pattern": "均衡价格|市场出清",
        "answer": "需求量等于供给量时的价格。此时市场上既无短缺也无过剩，供需力量达到平衡。"
      },
      {
        "pattern": "税负归宿|税收楔子",
        "answer": "税收在消费者支付价格与生产者收到价格之间打入一个楔子。税负归宿指税收最终由谁承担，取决于供需弹性：弹性小的一方承担更多。"
      },
      {
        "pattern": "吉芬商品|吉芬效应",
        "answer": "需求定律的例外：价格上升导致需求量增加的低档物品。通常因为收入效应（实际收入大降只能多买劣质品）大于替代效应。"
      },
      {
        "pattern": "价格上限|限价",
        "answer": "政府规定的最高合法价格。若低于均衡价格，会导致供不应求（短缺），常引发排队、黑市或质量下降。"
      },
      {
        "pattern": "需求量变动|需求变动",
        "answer": "**需求量变动**指仅由本商品价格变动引起的、沿原需求曲线的移动；**需求变动**指由收入、偏好等非价格因素引起的、整条需求曲线的平移。"
      }
    ]
  },
  "scenes": [
    {
      "id": "cover",
      "kind": "hero",
      "notes": "开场：抛出核心悖论——价格到底是谁决定的？是成本？是效用？引出本课核心：价格是供需力量碰撞的均衡结果。",
      "blocks": [
        {
          "id": "b_cover",
          "type": "hero",
          "intent": "封面：标题+一句副题",
          "size": "xl"
        }
      ]
    },
    {
      "id": "laws-intuition",
      "kind": "content",
      "eyebrow": "微观基础",
      "headline": "需求定律与供给定律",
      "lead": "价格变动不仅改变买卖双方的意愿，更重塑了资源的流向。",
      "notes": "破除“价格由成本决定”的误区，强调价格是供需双方博弈的结果。水便宜因为供给极大，钻石贵因为供给极度稀缺。区分“需求量”和“需求”是后续分析的基础，也是初学者最容易混淆的考点。",
      "blocks": [
        {
          "id": "b_laws_list",
          "type": "list",
          "intent": "需求定律（价涨量跌）与供给定律（价涨量增）的日常映射，引入水与钻石悖论",
          "size": "m"
        },
        {
          "id": "b_demand_shift",
          "type": "compare",
          "intent": "具象锚点：区分需求量变动（沿曲线移动）与需求变动（曲线平移）。左图：冰激凌涨价从5元到10元，少买两根（沿曲线）；右图：查出乳糖不耐受，无论多少钱都不买（曲线左移）",
          "size": "l"
        }
      ]
    },
    {
      "id": "equilibrium-dynamics",
      "kind": "content",
      "headline": "市场均衡与自发调节",
      "lead": "短缺与过剩是价格信号失灵的表象，而自发调节是市场恢复秩序的机制。",
      "notes": "强调均衡不是静态的点，而是一个动态收敛的过程。当价格低于均衡，短缺导致买者竞价推高价格；高于均衡，过剩导致卖者降价促销。蛛网模型提示了现实中的摩擦与时间滞后。",
      "blocks": [
        {
          "id": "b_eq_sim",
          "type": "sim",
          "engine": "widget",
          "intent": "交互演示：拖动价格水平线，观察高于均衡时的过剩面积与低于均衡时的短缺面积，以及价格向均衡点自发收敛的动态过程",
          "size": "xl"
        },
        {
          "id": "b_cobweb",
          "type": "callout",
          "intent": "现实摩擦：蛛网模型——供给存在时滞时，价格可能在均衡点附近振荡甚至发散",
          "size": "s"
        }
      ]
    },
    {
      "id": "math-derivation",
      "kind": "content",
      "eyebrow": "理论推导",
      "headline": "均衡的数学结构",
      "lead": "供需曲线背后是微观主体的最优化行为，均衡点是方程组的联立解。",
      "notes": "从直觉上升到数学，效用最大化推导需求，利润最大化推导供给。比较静态是经济学最核心的分析工具之一，看外生冲击如何内生地改变价格和数量。提醒学生注意模型成立的假设条件，这是后续批判的切入点。",
      "blocks": [
        {
          "id": "b_eq_formula",
          "type": "formula",
          "intent": "需求函数 $Q_d = a - bP$，供给函数 $Q_s = c + dP$，均衡条件 $Q_d = Q_s$，解出均衡价格 $P^* = (a-c)/(b+d)$",
          "size": "m"
        },
        {
          "id": "b_comp_static",
          "type": "flow",
          "intent": "比较静态分析流程：外生参数变动（如收入增加）→ 需求曲线右移 → 新旧均衡对比（$P^*$ 上升，$Q^*$ 上升）",
          "size": "m"
        },
        {
          "id": "b_assumptions",
          "type": "callout",
          "intent": "模型隐含假设：完全竞争（买卖双方都是价格接受者）、价格连续可变、无摩擦调整",
          "size": "s"
        }
      ]
    },
    {
      "id": "tax-wedge",
      "kind": "content",
      "eyebrow": "政策分析",
      "headline": "税收楔子与税负归宿",
      "lead": "税收在供需之间打入一个楔子，最终谁买单不由谁交税决定，而由弹性决定。",
      "notes": "核心难点：法定纳税人与实际税负承担者的分离。无论向谁征税，税收楔子都会导致买方支付价上升、卖方收到价下降。弹性小的一方更难逃离市场，因此承担更多税负。无谓损失是市场效率的净损失。",
      "blocks": [
        {
          "id": "b_tax_sim",
          "type": "sim",
          "engine": "widget",
          "intent": "交互演示：调整供需曲线的弹性（斜率），观察对消费者或生产者征税时，税负分摊比例的变化与无谓损失面积",
          "size": "xl"
        },
        {
          "id": "b_elasticity_rule",
          "type": "callout",
          "intent": "弹性法则：需求越缺乏弹性（如香烟），消费者承担的税负比例越高；供给越缺乏弹性，生产者承担越多",
          "size": "s"
        }
      ]
    },
    {
      "id": "price-control",
      "kind": "content",
      "headline": "价格管制与市场扭曲",
      "lead": "限价与配额看似保护弱势群体，实则切断了价格信号，导致非均衡状态持续。",
      "notes": "回答“为什么限价反而租不到房”：价格被压低，需求量增加但供给量减少，短缺出现。短缺引发寻租（排队、黑市、走后门），长期看供给方缺乏维护动力，质量下降。政策初衷与结果的背离。",
      "blocks": [
        {
          "id": "b_control_diagram",
          "type": "diagram",
          "intent": "因果链条：价格上限低于均衡 → 供不应求（短缺） → 排队/黑市/质量下降；价格下限高于均衡 → 供过于求（过剩） → 失业/销毁产能",
          "size": "l"
        },
        {
          "id": "b_rent_control",
          "type": "list",
          "intent": "现实案例：纽约租金管制导致租房难且年久失修；最低工资导致部分低技能劳动力失业",
          "size": "m"
        }
      ]
    },
    {
      "id": "model-limits",
      "kind": "content",
      "eyebrow": "批判性思维",
      "headline": "供需模型的失效边界",
      "lead": "当理性人假设和信息完全假设崩塌，需求曲线可能向上倾斜，甚至直接消失。",
      "notes": "回应批判性视角：股票追涨是因为预期未来价格更高（需求曲线右移，而非沿曲线移动）；网红店排队是羊群效应；柠檬市场中买家无法分辨质量，只愿出低价，逼走好车，最终市场萎缩。这些不是推翻模型，而是提醒我们注意前提假设。",
      "blocks": [
        {
          "id": "b_anomaly_grid",
          "type": "grid",
          "intent": "四个反例矩阵：吉芬商品（低档必需品价涨量增）、凡勃伦效应（炫耀性消费价涨显身份）、投机预期（追涨杀跌）、柠檬市场（信息不对称导致劣币驱逐良币）",
          "size": "l"
        },
        {
          "id": "b_model_quote",
          "type": "statement",
          "intent": "模型是地图，不是疆域本身。理解边界才能正确使用工具。",
          "size": "m"
        }
      ]
    },
    {
      "id": "finale",
      "kind": "hero",
      "notes": "收尾：重申价格是供需博弈的结果，而非由单方成本或效用决定。鼓励学生在现实中用供需框架分析问题，同时保持对假设的警觉。",
      "blocks": [
        {
          "id": "b_finale",
          "type": "hero",
          "intent": "收尾：价格是结果，而非原因",
          "size": "xl"
        }
      ]
    }
  ]
}
